rsion": target.version, "limit": 1 if kind == "incomplete" else 100, }, queue_on_failure=False, ) assert preview["complete"] is (kind != "incomplete") selected_facts = [copy.id] selected_sources = [ source for candidate in preview["candidates"] if candidate["fact_id"] == copy.id for source in candidate["required_source_event_ids"] ] if kind == "duplicate_fact": selected_facts *= 2 if kind == "duplicate_source": assert selected_sources selected_sources *= 2 before = _snapshot(domain) client.outbox.append( { "event_id": "valid-pending-review-capture", "context": context.model_dump(mode="json"), "occurred_at": datetime.now(timezone.utc).isoformat(), "role": "user", "content": "Keep the review queue intact.", "source_kind": "hermes_memory_provider", } ) client._outbox_drained = False pending = client.outbox.pending() result = await client.request( "forget_related", { "context": context.model_dump(mode="json"), "fact_id": target.id, "expected_version": target.version, "preview_digest": preview["preview_digest"], "preview_limit": preview["limit"], "selected_fact_ids": selected_facts, "selected_source_event_ids": selected_sources, }, queue_on_failure=False, ) > assert result["status"] == "rejected" E AssertionError: assert 'degraded' == 'rejected' E E - rejected E + degraded
